// Thin JS binding for cmochicode — generated from mochi_modules/manifest.json.
// Native plugin contract: the DLL exports mbjs_init_module() only;
// engine symbols (MBJS_*) are resolved from the host image at init time
// (see mbjs_runtime.h). No JS face exists yet, so this entry exposes the
// documented loader path and the real runtime export names.
import * as std from 'mbjs:std';
import * as os from 'mbjs:os';

export const module = "cmochicode";
export const entryPoint = 'mbjs_init_module';
export const runtimeExports = [
  "compile",
  "compileFile",
  "version"
];

export function tryLoad(loadNative) {
    try { return loadNative("cmochicode_x86_64.dll"); }
    catch (e) { return { fallback: true, std, os, reason: String(e) }; }
}

export default { module, entryPoint, runtimeExports, tryLoad };
